<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
import {invoke} from '@tauri-apps/api/core'
import {useI18n} from '@/lib/i18n'
import {savedSaleText,savedSaleSummary,type SavedSale,type SavedInvoice} from '@/lib/savedSale'
const props=defineProps<{invoiceId?:string|null}>(),emit=defineEmits<{loaded:[sale:SavedInvoice]}>()
const {pick,formatCurrency,formatDateTime}=useI18n(),sale=ref<SavedSale|null>(null),busy=ref(false),error=ref(''),printing=ref(false),copyFallback=ref(false)
const text=computed(()=>sale.value?savedSaleText(sale.value,formatCurrency):'')
let version=0
async function load(){const current=++version;busy.value=true;error.value='';try{const result=await invoke<SavedSale|null>('saved_sale',{invoiceId:props.invoiceId||null});if(current!==version)return null;sale.value=result;if(result)emit('loaded',result.invoice);return result}catch(e){if(current===version)error.value=String(e);return null}finally{if(current===version)busy.value=false}}
watch(()=>props.invoiceId,()=>void load(),{immediate:true})
async function print(){if(busy.value)return;const result=await load();if(!result)return;printing.value=true;await nextTick();const style=document.createElement('style');style.textContent='@page { size: 80mm 297mm; margin: 3mm; }';document.head.appendChild(style);document.body.classList.add('printing-saved-sale');const clean=()=>{style.remove();document.body.classList.remove('printing-saved-sale');printing.value=false};window.addEventListener('afterprint',clean,{once:true});try{window.print()}catch(e){window.removeEventListener('afterprint',clean);clean();error.value=String(e)}}
async function copy(){const result=await load();if(!result)return;try{await navigator.clipboard.writeText(text.value);copyFallback.value=true}catch{copyFallback.value=true}}
async function whatsapp(){const result=await load();if(!result?.invoice.customer_phone)return;try{await invoke('open_whatsapp_receipt',{phone:result.invoice.customer_phone,message:savedSaleSummary(result,formatCurrency)})}catch(e){error.value=String(e)}}
defineExpose({print,copy,whatsapp,load})
</script>
<template>
 <section class="saved-sale-actions"><h3>{{pick('Last saved sale','آخری محفوظ فروخت')}}</h3><p v-if="busy" role="status">{{pick('Loading saved invoice…','محفوظ انوائس لوڈ ہو رہی ہے…')}}</p><p v-if="error" role="alert">{{error}}</p>
 <template v-if="sale"><bdi>{{sale.invoice.invoice_number}}</bdi><strong>{{formatCurrency(sale.invoice.net_amount)}}</strong><small>{{sale.invoice.payment_method==='credit'?pick('Posted to customer account','گاہک کے کھاتے میں درج'):pick('Completed payment','ادائیگی مکمل')}}</small><small v-if="sale.invoice.customer_phone">{{sale.invoice.customer_phone}}</small><div class="saved-sale-buttons"><button type="button" :disabled="busy" @click="print">{{pick('Reprint receipt','رسید دوبارہ پرنٹ')}}</button><button type="button" :disabled="busy" @click="copy">{{pick('Copy SMS receipt','ایس ایم ایس رسید کاپی')}}</button><button v-if="sale.invoice.customer_phone" type="button" :disabled="busy" @click="whatsapp">{{pick('WhatsApp draft','واٹس ایپ مسودہ')}}</button></div><small>{{pick('Saved invoice data; independent of the current cart.','محفوظ انوائس کا ڈیٹا؛ موجودہ کارٹ سے الگ۔')}}</small><textarea v-if="copyFallback" :value="text" readonly rows="5" :aria-label="pick('Saved receipt text — paste into your SMS app','محفوظ رسید — ایس ایم ایس ایپ میں پیسٹ کریں')" @focus="($event.target as HTMLTextAreaElement).select()"/></template>
 <button v-if="!sale||error" type="button" :disabled="busy" @click="load">{{pick('Recover last saved sale','آخری محفوظ فروخت بازیاب کریں')}}</button>
 </section>
 <Teleport to="body"><section v-if="printing&&sale" class="saved-sale-print"><header><h1>{{sale.shop?.company_name||'Pharmacy POS'}}</h1><p>{{sale.shop?.company_address}}</p><p>{{sale.shop?.company_phone}}</p><p>{{sale.shop?.receipt_header}}</p><h2>{{pick('Sales receipt','فروخت کی رسید')}}</h2></header><p>{{sale.invoice.invoice_number}}</p><p>{{formatDateTime(sale.invoice.invoice_date)}}</p><p>{{pick('Customer','گاہک')}}: {{sale.invoice.customer_name}}</p><p>{{pick('Cashier','کیشئر')}}: {{sale.invoice.cashier_name}}</p><p>{{pick('Payment','ادائیگی')}}: {{sale.invoice.payment_method==='credit'?pick('Credit / Udhar','کریڈٹ / ادھار'):sale.invoice.payment_method}}</p><p v-if="sale.invoice.patient_name">{{pick('Patient','مریض')}}: {{sale.invoice.patient_name}}</p><p v-if="sale.invoice.doctor_name">{{pick('Doctor','ڈاکٹر')}}: {{sale.invoice.doctor_name}}</p><p v-if="sale.invoice.prescription_note">{{pick('Prescription','نسخہ')}}: {{sale.invoice.prescription_note}}</p><table><thead><tr><th>{{pick('Item / batch' ,'آئٹم / بیچ')}}</th><th>{{pick('Qty','تعداد')}}</th><th>{{pick('Total','کل')}}</th></tr></thead><tbody><tr v-for="l in sale.items" :key="l.id"><td>{{l.product_name}}<small>{{l.batch_number}}</small><small v-if="sale.shop?.show_drap&&l.controlled_substance&&l.drap_registration_number">DRAP: {{l.drap_registration_number}}</small></td><td>{{l.sale_quantity??l.quantity}} {{l.sale_quantity==null?pick('units','اکائیاں'):l.is_loose_sale?pick('loose','کھلی'):pick('packs','پیک')}}<small v-if="l.bonus_quantity">+{{l.bonus_quantity}} {{pick('free','مفت')}}</small></td><td>{{formatCurrency(l.line_total)}}</td></tr></tbody></table><p>{{pick('Subtotal','ذیلی کل')}}: {{formatCurrency(sale.invoice.total_amount)}}</p><p>{{pick('Tax','ٹیکس')}}: {{formatCurrency(sale.invoice.tax_amount)}}</p><p>{{pick('Discount','رعایت')}}: {{formatCurrency(sale.invoice.discount_amount)}}</p><h2>{{sale.invoice.payment_method==='credit'?pick('Charged to account','کھاتے میں درج رقم'):pick('Paid','ادا شدہ')}}: {{formatCurrency(sale.invoice.net_amount)}}</h2><p v-if="sale.invoice.payment_method==='credit'">{{pick('Account balance at this sale','اس فروخت پر کھاتے کا بقایا')}}: {{formatCurrency(Number(sale.invoice.previous_balance||0)+sale.invoice.net_amount)}}</p><p>{{pick('Received','وصول')}}: {{formatCurrency(sale.invoice.received_amount||0)}}</p><p>{{pick('Change','واپسی')}}: {{formatCurrency(sale.invoice.change_amount||0)}}</p><p>{{sale.invoice.notes}}</p><footer>{{sale.shop?.receipt_footer||pick('Thank you for your purchase.','آپ کی خریداری کا شکریہ۔')}}</footer></section></Teleport>
</template>
<style scoped>
.saved-sale-actions{display:grid;gap:.3rem;padding:.6rem;border:1px solid var(--color-border);border-radius:7px;background:var(--color-background);font-size:.72rem}.saved-sale-actions h3{font-size:.8rem;font-weight:700}.saved-sale-actions strong{color:var(--color-primary)}.saved-sale-actions small{color:var(--color-text-secondary);font-size:.68rem}.saved-sale-buttons{display:flex;flex-wrap:wrap;gap:.3rem}.saved-sale-actions button{padding:.3rem .4rem;border:1px solid var(--color-border);border-radius:5px;background:var(--color-surface);color:var(--color-text-primary);font-size:.7rem}.saved-sale-actions textarea{width:100%;background:var(--color-surface);color:var(--color-text-primary)}.saved-sale-actions [role=alert]{color:var(--color-danger)}
</style>
<style>
.saved-sale-print{display:none}@media print{body.printing-saved-sale>*:not(.saved-sale-print){display:none!important}body.printing-saved-sale>.saved-sale-print{display:block!important;width:72mm;background:white;color:black;font:9pt Arial,sans-serif}.saved-sale-print header,.saved-sale-print footer{text-align:center}.saved-sale-print h1{font-size:15pt;font-weight:bold}.saved-sale-print h2{font-size:11pt;font-weight:bold;margin:3mm 0}.saved-sale-print table{width:100%;border-collapse:collapse;table-layout:fixed;margin:3mm 0}.saved-sale-print th,.saved-sale-print td{text-align:start;vertical-align:top;padding:2mm 1mm;border-bottom:1px solid #999;overflow-wrap:anywhere}.saved-sale-print th:first-child{width:45%}.saved-sale-print small{display:block}.saved-sale-print p{margin:1mm 0;overflow-wrap:anywhere}}
</style>
